mapper.select:
SELECT P.PRODUCT_ID AS productId, P.CATEGORY_ID AS categoryId, P.PRODUCT_NAME AS productName, P.PRICE AS price, P.STOCK_QUANTITY AS stockQuantity, P.PRODUCT_STATUS AS productStatus, P.CREATED_AT AS createdAt, P.UPDATED_AT AS updatedAt, ( SELECT PI.IMAGE_URL FROM PRODUCT_IMAGE PI WHERE PI.PRODUCT_ID = P.PRODUCT_ID AND PI.IMAGE_TYPE = 'THUMBNAIL' LIMIT 1 ) AS thumbnailUrl FROM PRODUCT P AND P.PRODUCT_STATUS != 'DELETE' AND P.PRODUCT_STATUS = #{productStatus}
AND CAST(P.PRODUCT_ID AS CHAR) LIKE CONCAT('%', #{keyword}, '%')
AND P.PRODUCT_NAME LIKE CONCAT('%', #{keyword}, '%')
ORDER BY P.CREATED_AT DESC LIMIT #{pageSize} OFFSET #{offset}

